 const go=(id,push=true)=>{const n=fsGet(id);if(!n||n.type!=='folder')return;st.path=id;if(push){st.history=st.history.slice(0,st.hi+1);if(st.history.at(-1)!==id)st.history.push(id);st.hi=st.history.length-1}selected.clear();anchor='';save();draw()};
