 const statusOf=n=>st.evidence[n.id]?'evidence':n.status;
 const statusHTML=n=>{const s=statusOf(n),labels={ok:'✓ OK',locked:'▣ Locked · NX-4',corrupted:'! Corrupted',deleted:'⌫ Deleted',recovered:'↺ Recovered',evidence:'◆ Evidence'},extra=n.parent==='recovered'&&s==='locked'?'<span class="fx-badge recovered">↺ Recovered</span>':'';return `<span class="fx-badge ${s}">${labels[s]||s}</span>${extra}`};
 const fileIcon=n=>icon(n.type==='folder'?'folder':n.type in ICONS?n.type:'doc',`fx-icon fx-icon-${n.type}`);
 const currentRows=()=>{const key=st.sort.key,dir=st.sort.dir;return fsAll().filter(n=>n.parent===st.path&&n.name.toLowerCase().includes(query)).sort((a,c)=>{if(a.type==='folder'&&c.type!=='folder')return -1;if(c.type==='folder'&&a.type!=='folder')return 1;return String(a[key]||'').localeCompare(String(c[key]||''),undefined,{numeric:true})*dir})};
 const itemHTML=n=>`<span class="fx-name">${fileIcon(n)}<span><b>${st.evidence[n.id]?'★ ':''}${n.name}</b>${n.parent==='recovered'?`<small>From ${n.original||'local volume'} · recovered ${n.recoveryAt}</small>`:''}</span></span>`;
 const draw=()=>{rows=currentRows();b.querySelectorAll('[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===st.path));$('.fx-count',b).textContent=recoveredCount();$('.fx-crumb',b).innerHTML=ancestors(st.path).map((n,i,a)=>`<button data-crumb="${n.id}" ${i===a.length-1?'aria-current="page"':''}>${n.name}</button>${i<a.length-1?'<span>›</span>':''}`).join('');
  const folders=fsAll().filter(n=>n.type==='folder');mobile.innerHTML=folders.map(n=>`<option value="${n.id}" ${n.id===st.path?'selected':''}>${n.path}</option>`).join('');b.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===st.view));
  if(!rows.length){files.innerHTML=`<div class="fx-empty">${st.path==='recovered'?'No files recovered yet. Check the Recycle Bin.':query?'No items match this search.':'This folder is empty.'}</div>`}
  else if(st.view==='details')files.innerHTML=`<table class="fx-table project-table"><thead><tr>${[['name','Name'],['status','Status'],['type','Type'],['size','Size'],['modified','Modified']].map(([k,l])=>`<th><button data-sort="${k}">${l}${st.sort.key===k?(st.sort.dir>0?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${rows.map(n=>`<tr tabindex="0" data-node="${n.id}" aria-selected="${selected.has(n.id)}" class="${n.status==='deleted'?'is-deleted':''}"><td>${itemHTML(n)}</td><td>${statusHTML(n)}</td><td>${fsType(n)}</td><td>${n.size||'—'}</td><td>${n.modified}</td></tr>`).join('')}</tbody></table>`;
  else files.innerHTML=`<div class="fx-${st.view}">${rows.map(n=>`<button data-node="${n.id}" aria-selected="${selected.has(n.id)}" class="fx-item ${n.status==='deleted'?'is-deleted':''}">${itemHTML(n)}${statusHTML(n)}${st.view==='list'?`<span>${fsType(n)}</span><span>${n.modified}</span>`:''}</button>`).join('')}</div>`;
  $('.fx-status',b).textContent=`${rows.length} item${rows.length===1?'':'s'} · ${selected.size} selected`;preview.hidden=!st.preview;renderPreview();save()};
 const renderPreview=()=>{if(!st.preview)return;const n=fsGet([...selected][0]);preview.innerHTML=n?`<div class="fx-preview-icon">${fileIcon(n)}</div><h3>${n.name}</h3>${statusHTML(n)}<dl><dt>Type</dt><dd>${fsType(n)}</dd><dt>Size</dt><dd>${n.size||'—'}</dd><dt>Modified</dt><dd>${n.modified}</dd>${n.original?`<dt>Original</dt><dd>${n.original}</dd>`:''}</dl><button class="btn" data-props="${n.id}">Properties</button>`:'<p class="muted">Select an item to preview its properties.</p>'};
 const select=(id,e={})=>{if(e.shiftKey&&anchor){const a=rows.findIndex(n=>n.id===anchor),z=rows.findIndex(n=>n.id===id);if(a>=0&&z>=0){if(!e.ctrlKey)selected.clear();rows.slice(Math.min(a,z),Math.max(a,z)+1).forEach(n=>selected.add(n.id))}}else if(e.ctrlKey){selected.has(id)?selected.delete(id):selected.add(id);anchor=id}else{selected=new Set([id]);anchor=id}draw()};
 const properties=n=>modal('Properties — '+n.name,`<dl class="fx-props"><dt>Name</dt><dd>${n.name}</dd><dt>Full path</dt><dd>${n.path}</dd><dt>Type</dt><dd>${fsType(n)}</dd><dt>Size</dt><dd>${n.size||'—'}</dd><dt>Created</dt><dd>${n.created}</dd><dt>Modified</dt><dd>${n.modified}</dd><dt>Owner</dt><dd>${n.owner}</dd><dt>Attributes</dt><dd>${n.attrs.join(', ')}</dd><dt>Integrity</dt><dd>${fsChecksum(n)}</dd><dt>Status</dt><dd>${statusOf(n)}</dd>${n.original?`<dt>Original location</dt><dd>${n.original}</dd><dt>Recovered</dt><dd>${n.recoveryAt||'not recovered'}</dd>`:''}</dl>`);
 const roError=a=>{notify(`${a} failed: /dsk0 is mounted read-only`);$('.fx-progress',b).textContent=`System error: ${a} is unavailable on a read-only volume.`};
 const reconstruct=n=>{modal('Repair damaged filename',`<p>The file header is intact, but one filename byte is missing.</p><label for="dg">AUD_0</label><select id="dg">${[...Array(10).keys()].map(x=>`<option>${x}</option>`).join('')}</select><span>17.wav</span><p><button class="btn" id="tr">Reconstruct index</button></p><p id="repairmsg" class="mono"></p>`);$('#tr').onclick=()=>{if($('#dg').value==='3'){S.solved.file=1;st.recovered['audio-recovered']='03.17.2031 00:17';ev('file');pulse();notify('Recovered: AUD_0317.wav');$('#modal').close();save();draw()}else{$('#repairmsg').className='mono err';$('#repairmsg').textContent='Header mismatch. File remains damaged.'}}};
 const recover=n=>{if(n.id!=='final-deleted'){st.restored[n.id]='03.17.2031 00:17';notify(`Restored ${n.name} to Recovered Files`);save();draw();return}let p=0,m=$('.fx-progress',b);const iv=setInterval(()=>{p+=rm()?100:10;m.textContent=`Recovering archive… ${p}%`;if(p>=100){clearInterval(iv);S.flags.enc=1;st.recovered['final-recovered']='03.17.2031 00:17';ev('enc');pulse();notify('Restored FINAL_MESSAGE.enc (locked)');save();draw()}},200)};
 const openNode=n=>{if(!n)return;if(n.type==='folder')return go(n.id);if(n.status==='deleted')return recover(n);if(n.status==='locked')return modal('Access denied',`<p class="warn">Access denied — clearance NX-4.</p><p class="meta">${n.path}</p>`);if(n.type==='wav')return n.status==='corrupted'?reconstruct(n):open('audio');if(n.id==='readme'){S.lore=1;save()}if(n.type==='txt'||n.type==='doc')return modal(n.name,`<p class="meta">${n.path}</p><article class="fx-reader">${n.text||'No readable preview is available.'}</article>`);if(n.type==='enc')modal('Encrypted archive','Open this recovered archive from Terminal.')};
