 const closeMenu=()=>{menu.hidden=true;menu.innerHTML=''};
 const menuAction=(a,n)=>{closeMenu();if(a==='open')openNode(n);else if(a==='openwith')modal('Open with…',`<p>${n.type==='wav'?'Audio Lab':n.type==='txt'?'Text Reader':'System Viewer'} is the registered application for this file type.</p>`);else if(a==='props')properties(n||fsGet(st.path));else if(a==='copy'){navigator.clipboard?.writeText(n.path);notify('Path copied to clipboard')}else if(a==='evidence'){st.evidence[n.id]=!st.evidence[n.id];save();draw()}else if(a==='restore'||a==='recover')n.status==='corrupted'?reconstruct(n):recover(n);else if(a==='hash')inspect(n);else if(a==='newwin'){st.path=n.id;save();const id='explorer-'+Date.now();APPS[id]={t:'File Explorer',i:'folder',b:x=>buildFiles(x,'files')};open(id)}else if(a==='refresh')draw();else if(a.startsWith('sort-')){st.sort={key:a.slice(5),dir:1};draw()}else if(a.startsWith('view-')){st.view=a.slice(5);draw()}else if(['rename','delete','paste'].includes(a))roError(a[0].toUpperCase()+a.slice(1))};
 const showMenu=(x,y,n)=>{const ro=(a,l)=>`<button role="menuitem" data-action="${a}" aria-disabled="true" title="Disk is mounted read-only">${l}</button>`,item=(a,l)=>`<button role="menuitem" data-action="${a}">${l}</button>`;let h='';if(n?.type==='folder')h=item('open','Open')+item('newwin','Open in new window')+item('props','Properties')+'<span></span>'+ro('rename','Rename')+ro('delete','Delete')+ro('paste','Paste');else if(n)h=item('open','Open')+item('openwith','Open with…')+item('props','Properties')+item('copy','Copy path')+item('evidence',st.evidence[n.id]?'Unmark evidence':'Mark as evidence')+(n.status==='deleted'?item('restore','Restore'):'')+(['corrupted','deleted'].includes(n.status)?item('recover','Recover'):'')+item('hash','Inspect hash')+'<span></span>'+ro('rename','Rename')+ro('delete','Delete')+ro('paste','Paste');else h=item('refresh','Refresh')+item('sort-name','Sort by name')+item('sort-modified','Sort by modified')+item('view-details','View details')+item('view-list','View list')+item('view-icons','View icons')+item('props','Properties')+'<span></span>'+ro('paste','Paste');menu.dataset.node=n?.id||'';menu.innerHTML=h;menu.hidden=false;menu.style.left=Math.min(x,innerWidth-230)+'px';menu.style.top=Math.min(y,innerHeight-360)+'px';menu.querySelector('button')?.focus()};
 files.addEventListener('click',e=>{const x=e.target.closest('[data-node]');if(x)select(x.dataset.node,e);const s=e.target.closest('[data-sort]');if(s){const k=s.dataset.sort;st.sort={key:k,dir:st.sort.key===k?-st.sort.dir:1};draw()}});files.addEventListener('dblclick',e=>{const x=e.target.closest('[data-node]');if(x)openNode(fsGet(x.dataset.node))});
