function buildBrowser(b){b.innerHTML=`<div class="toolbar"><button>‹</button><button>›</button><button>↻</button><span class="address">nexus://local/recovery/overview</span><button>⋮</button></div><div style="padding:28px;max-width:680px"><p class="meta">NEXUS-7 INTERNAL SERVICE</p><h2 style="margin-bottom:8px">Local recovery console</h2><p class="muted">External browsing is unavailable while the workstation is in isolated recovery mode. Local services remain accessible.</p><table class="project-table"><tbody><tr><td>Volume index</td><td class="ok">Operational</td><td>/dsk0</td></tr><tr><td>Recovery daemon</td><td class="ok">Running</td><td>localhost:4170</td></tr><tr><td>Evidence cache</td><td class="amber">${S.ev.length} / 6 indexed</td><td>local only</td></tr><tr><td>Remote uplink</td><td class="err">Disconnected</td><td>route unavailable</td></tr></tbody></table></div>`}
function buildBoard(b){const cards=[['Decoded message',S.solved.caesar],['Recording filename',S.solved.file],['Audio sequence',S.solved.audio],['Recovered archive',S.flags.enc],['Final message',S.solved.term]];b.innerHTML=`<div class="toolbar"><button>Timeline</button><button>Sources</button><span class="address">Case 0317 · Local evidence index</span></div><div style="padding:14px"><p class="meta">Evidence is indexed automatically from verified local sources.</p><table class="project-table"><thead><tr><th>Artifact</th><th>Source</th><th>Integrity</th><th>Status</th></tr></thead><tbody>${cards.map((c,i)=>`<tr><td>${c[0]}</td><td>${['Messages','Mail','Audio Lab','Recycle Bin','Terminal'][i]}</td><td>${c[1]?'verified':'pending'}</td><td class="${c[1]?'ok':'state'}">${c[1]?'indexed':'not discovered'}</td></tr>`).join('')}</tbody></table></div><div class="statusbar"><span>${S.ev.length} evidence records</span><span>Case cache encrypted</span></div>`}
function buildSettings(b){b.innerHTML=`<div class="settings-grid"><nav class="app-sidebar"><h3>System</h3><button class="active">${icon('monitor')}Display</button><button>${icon('volume')}Sound</button><button>${icon('settings')}Accessibility</button><button>${icon('wifi')}Network</button><button>${icon('note')}About</button></nav><main class="settings-panel"><p class="meta">DISPLAY & ACCESSIBILITY</p><div class="setting-row"><span><b>Interface scale</b><small>Adjust text and control size</small></span><input id="deskfs" type="range" min="14" max="20" value="${parseInt(getComputedStyle(document.documentElement).fontSize)}"></div><div class="setting-row"><span><b>Reduced motion</b><small>Disable window and system animations</small></span><button id="deskrm" class="switch ${document.body.classList.contains('rm')?'on':''}" aria-pressed="${document.body.classList.contains('rm')}"></button></div><div class="setting-row"><span><b>High contrast focus</b><small>Use the existing amber accent for keyboard focus</small></span><button class="switch on" aria-pressed="true"></button></div><div class="setting-row"><span><b>System sounds</b><small>Audio alerts and application feedback</small></span><button class="switch" aria-pressed="false"></button></div></main></div>`;$('#deskfs',b).oninput=e=>document.documentElement.style.setProperty('--fs',e.target.value+'px');$('#deskrm',b).onclick=e=>{document.body.classList.toggle('rm');e.currentTarget.classList.toggle('on');e.currentTarget.setAttribute('aria-pressed',e.currentTarget.classList.contains('on'))};b.querySelectorAll('.switch:not(#deskrm)').forEach(x=>x.onclick=()=>{x.classList.toggle('on');x.setAttribute('aria-pressed',x.classList.contains('on'))})}
/* ---- audio ---- */
let A={ctx:0,t:0,iv:0,playing:false,gain:0,mute:false,src:0};
const audioStop=()=>{clearInterval(A.iv);A.playing=false;try{A.src&&A.src.stop()}catch{}A.src=0};
function buildAudio(b){if(!S.solved.file){b.innerHTML='<p class="locked">🔒 Locked. No readable audio file is indexed. Reconstruct the corrupted filename in File Explorer.</p>';return}
 b.innerHTML=`<canvas aria-label="Waveform and frequency spectrum, bins 1 to 32"></canvas><div class="ctl"><button class="btn" id="pp" aria-label="Play">▶ Play</button><input type="range" id="sc" min="0" max="60" value="0" aria-label="Scrub"><span class="mono" id="tm">0:00 / 1:00</span></div><div class="ctl"><label for="vol">Volume</label><input type="range" id="vol" min="0" max="100" value="30"><button class="btn" id="mu" aria-pressed="false">Mute</button><button class="btn" id="tx">Transcript</button></div><p class="mono muted">Bins 1–32 shown left to right.</p>`;
 const cv=$('canvas',b),g=cv.getContext('2d'),HID=[[10,4],[20,1],[30,23],[40,14]];
 const draw=()=>{const w=cv.width=cv.clientWidth,h=cv.height=150;g.fillStyle='#030607';g.fillRect(0,0,w,h);const bw=w/32;
  for(let i=1;i<=32;i++){let v=Math.random()*(A.playing?.35:.12);HID.forEach(([t,bin])=>{if(bin===i&&A.t>=t&&A.t<t+6)v=.85});g.fillStyle=v>.6?'#FFC857':'#55D6C2';g.fillRect((i-1)*bw+1,h-v*h,bw-2,v*h)}
  g.fillStyle='#829397';g.font='10px monospace';[1,4,8,14,16,23,32].forEach(n=>g.fillText(n,(n-1)*bw+2,10))};
 const upd=()=>{$('#sc',b).value=A.t;const f=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');$('#tm',b).textContent=f(A.t)+' / 1:00';if(A.t>=46&&!S.solved.audio){S.solved.audio=1;ev('audio');pulse();notify('Sequence logged: 4 1 23 14')}};
 const loop=()=>{clearInterval(A.iv);A.iv=setInterval(()=>{if(A.playing){A.t=Math.min(60,A.t+.2);if(A.t>=60)toggle(false)}draw();upd()},200)};
 const toggle=p=>{A.playing=p;$('#pp',b).textContent=p?'❚❚ Pause':'▶ Play';$('#pp',b).setAttribute('aria-label',p?'Pause':'Play');
  if(p&&!A.src){try{A.ctx=A.ctx||new AudioContext();const buf=A.ctx.createBuffer(1,A.ctx.sampleRate*2,A.ctx.sampleRate),d=buf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;A.src=A.ctx.createBufferSource();A.src.buffer=buf;A.src.loop=true;A.gain=A.ctx.createGain();A.gain.gain.value=A.mute?0:$('#vol',b).value/1000;A.src.connect(A.gain).connect(A.ctx.destination);A.src.start()}catch{}}
  if(!p)audioStop(),A.playing=false};
 $('#pp',b).onclick=()=>toggle(!A.playing);$('#sc',b).oninput=e=>{A.t=+e.target.value;draw();upd()};
 $('#vol',b).oninput=e=>{if(A.gain)A.gain.gain.value=A.mute?0:e.target.value/1000};
 $('#mu',b).onclick=e=>{A.mute=!A.mute;e.target.setAttribute('aria-pressed',A.mute);e.target.textContent=A.mute?'Unmute':'Mute';if(A.gain)A.gain.gain.value=A.mute?0:$('#vol',b).value/1000};
 $('#tx',b).onclick=()=>modal('Transcript','[static, 60 seconds]<br>[00:10 low tone, bin four] [00:20 faint click, bin one] [00:30 rising whine, bin twenty-three] [00:40 breath, bin fourteen]<br>[faint voice, 00:52] "…count it. Then wait for morning."');
 loop();draw()}
